// Run it inside your labflow-lite project folder:  node cham-tai-may.mjs [test files…]
// (default: the test file(s) of this exercise). Needs the Playwright browsers (npx playwright install) and port 4173 free — Playwright builds the web app and starts the e2e server itself.
// What it does — same algorithm as the course's mutation labs: your tests must be GREEN on the correct code, then each
// planted bug is written into its file one at a time (the file is ALWAYS restored, even on Ctrl+C) and your tests must
// turn RED; harmless changes must keep them GREEN. It prints N/N when every check passes.
import { readFileSync, writeFileSync } from 'node:fs';
import { spawnSync } from 'node:child_process';

const DE = {
  "id": "tst-cl-7-3",
  "runner": "playwright",
  "config": null,
  "args": [
    "--project=chromium",
    "--repeat-each=3"
  ],
  "tests": [
    "e2e/dat-phong.spec.js"
  ],
  "dotBien": [
    {
      "file": "src/booking/service.js",
      "from": "b.start < end && start < b.end",
      "to": "b.start < end && start < b.start",
      "label": "the exact same slot can be booked twice"
    },
    {
      "file": "web/BookingForm.jsx",
      "from": "MESSAGES[res.data.error.code] ??",
      "to": "MESSAGES[res.status] ??",
      "label": "a taken slot shows a generic error"
    },
    {
      "file": "web/BookingForm.jsx",
      "from": "res.data.status === 'PENDING' ?",
      "to": "res.data.status !== 'PENDING' ?",
      "label": "pending and confirmed messages swapped"
    },
    {
      "file": "src/rules/booking.js",
      "from": "return seats > APPROVAL_SEATS;",
      "to": "return seats > APPROVAL_SEATS + 1;",
      "label": "31 seats is confirmed without approval"
    }
  ],
  "voHai": [
    {
      "file": "e2e/server.js",
      "from": "const app = createApp({ repo: createMemoryRepo(), auth });",
      "to": "const slowRepo = ((repo) => ({ ...repo, insert: async (b) => { await new Promise((ok) => setTimeout(ok, 1500)); return repo.insert(b); } }))(createMemoryRepo());\nconst app = createApp({ repo: slowRepo, auth });",
      "label": "slow server: every booking is saved 1.5 s later (web-first assertions keep waiting)"
    },
    {
      "file": "e2e/server.js",
      "from": "app.post('/api/login', async (req, res) => {",
      "to": "app.post('/api/login', async (req, res) => {\n  await new Promise((ok) => setTimeout(ok, 1500));",
      "label": "slow server: sign-in answers 1.5 s later"
    }
  ]
};

const tests = process.argv.slice(2).length ? process.argv.slice(2) : DE.tests;
const npx = (args) => spawnSync('npx', args, { encoding: 'utf8', shell: process.platform === 'win32' });
const run = () => (DE.runner === 'playwright'
  ? npx(['playwright', 'test', ...tests, ...(DE.args ?? ['--project=chromium'])])
  : npx(['vitest', 'run', ...(DE.config ? ['--config', DE.config] : []), ...tests, ...(DE.args ?? [])])).status;

let dangSua = null; // { file, goc } — trả lại nếu bị ngắt giữa chừng
const traLai = () => { if (dangSua) { writeFileSync(dangSua.file, dangSua.goc); dangSua = null; } };
process.on('SIGINT', () => { traLai(); process.exit(130); });

function voi(m, fn) {
  const goc = readFileSync(m.file, 'utf8');
  const n = goc.split(m.from).length - 1;
  if (n !== 1) {
    console.log(`  ? "${m.label}": the text to change was found ${n} times in ${m.file} — your file differs from the course version; copy ${m.file} from this exercise's starter and run again`);
    return null;
  }
  dangSua = { file: m.file, goc };
  writeFileSync(m.file, goc.replace(m.from, () => m.to));
  try { return fn(); } finally { traLai(); }
}

